export function t(key: string, lang?: string): string {
  const l = (lang || DEFAULT_LANG).toLowerCase() as LangCode;
  const entry = DICT[key];
  if (!entry) return key;
  return entry[l] || entry[DEFAULT_LANG] || key;
}

export function getLanguageDir(lang?: string): 'ltr' | 'rtl' {
  const found = SUPPORTED_LANGUAGES.find(l => l.code === (lang || DEFAULT_LANG).toLowerCase());
  return (found?.dir || 'ltr') as 'ltr' | 'rtl';
}

export function getLanguageByCode(code: string) {
  return SUPPORTED_LANGUAGES.find(l => l.code === code.toLowerCase());
}
